import{_ as e,o as r,c as h,a2 as t}from"./chunks/framework.EUByU7Iq.js";const p=JSON.parse('{"title":"第六章 股份有限公司的股份发行和转让","description":"","frontmatter":{"title":"第六章 股份有限公司的股份发行和转让","date":"2023-12-29T00:00:00.000Z","categories":["法律","公司法"],"tags":["法律","公司法"],"law_version":"2023修订（2023-12-29 公布，2024-07-01 施行）","v1_source":"blogs/CL/第六章：股份有限公司的股份发行和转让.md"},"headers":[],"relativePath":"blogs/CL/diliuzhang：gufenyouxiangongsidexingufenfaxinghezhuanrang.md","filePath":"blogs/CL/第六章：股份有限公司的股份发行和转让.md"}'),o={name:"blogs/CL/diliuzhang：gufenyouxiangongsidexingufenfaxinghezhuanrang.md"};function i(l,a,n,d,s,c){return r(),h("div",null,[...a[0]||(a[0]=[t('<h1 id="第六章-股份有限公司的股份发行和转让" tabindex="-1">第六章 股份有限公司的股份发行和转让 <a class="header-anchor" href="#第六章-股份有限公司的股份发行和转让" aria-label="Permalink to &quot;第六章 股份有限公司的股份发行和转让&quot;">​</a></h1><h3 id="第一百四十二条" tabindex="-1">第一百四十二条 <a class="header-anchor" href="#第一百四十二条" aria-label="Permalink to &quot;第一百四十二条&quot;">​</a></h3><p>二条公司的资本划分为股份。公司的全部股份，根据公司章程的规定择一采用面额股或者无面额股。采用面额股的，每一股的金额相等。 公司可以根据公司章程的规定将已发行的面额股全部转换为无面额股或者将无面额股全部转换为面额股。 采用无面额股的，应当将发行股份所得股款的二分之一以上计入注册资本。</p><h3 id="第一百四十三条" tabindex="-1">第一百四十三条 <a class="header-anchor" href="#第一百四十三条" aria-label="Permalink to &quot;第一百四十三条&quot;">​</a></h3><p>三条股份的发行，实行公平、公正的原则，同类别的每一股份应当具有同等权利。 同次发行的同类别股份，每股的发行条件和价格应当相同；认购人所认购的股份，每股应当支付相同价额。</p><h3 id="第一百四十四条" tabindex="-1">第一百四十四条 <a class="header-anchor" href="#第一百四十四条" aria-label="Permalink to &quot;第一百四十四条&quot;">​</a></h3><p>四条公司可以按照公司章程的规定发行下列与普通股权利不同的类别股： （一）优先或者劣后分配利润或者剩余财产的股份； （二）每一股的表决权数多于或者少于普通股的股份； （三）转让须经公司同意等转让受限的股份； （四）国务院规定的其他类别股。 公开发行股份的公司不得发行前款第二项、第三项规定的类别股；公开发行前已发行的除外。 公司发行本条第一款第二项规定的类别股的，对于监事或者审计委员会成员的选举和更换，类别股与普通股每一股的表决权数相同。</p><h3 id="第一百四十五条" tabindex="-1">第一百四十五条 <a class="header-anchor" href="#第一百四十五条" aria-label="Permalink to &quot;第一百四十五条&quot;">​</a></h3><p>五条发行类别股的公司，应当在公司章程中载明以下事项： （一）类别股分配利润或者剩余财产的顺序； （二）类别股的表决权数； （三）类别股的转让限制； （四）保护中小股东权益的措施； （五）股东会认为需要规定的其他事项。</p><h3 id="第一百四十六条" tabindex="-1">第一百四十六条 <a class="header-anchor" href="#第一百四十六条" aria-label="Permalink to &quot;第一百四十六条&quot;">​</a></h3><p>六条发行类别股的公司，有本法第一百一十六条第三款规定的事项等可能影响类别股股东权利的，除应当依照第一百一十六条第三款的规定经股东会决议外，还应当经出席类别股股东会议的股东所持表决权的三分之二以上通过。 公司章程可以对需经类别股股东会议决议的其他事项作出规定。</p><h3 id="第一百四十七条" tabindex="-1">第一百四十七条 <a class="header-anchor" href="#第一百四十七条" aria-label="Permalink to &quot;第一百四十七条&quot;">​</a></h3><p>七条公司的股份采取股票的形式。股票是公司签发的证明股东所持股份的凭证。 公司发行的股票，应当为记名股票。</p><h3 id="第一百四十八条" tabindex="-1">第一百四十八条 <a class="header-anchor" href="#第一百四十八条" aria-label="Permalink to &quot;第一百四十八条&quot;">​</a></h3><p>八条面额股股票的发行价格可以按票面金额，也可以超过票面金额，但不得低于票面金额。</p><h3 id="第一百四十九条" tabindex="-1">第一百四十九条 <a class="header-anchor" href="#第一百四十九条" aria-label="Permalink to &quot;第一百四十九条&quot;">​</a></h3><p>九条股票采用纸面形式或者国务院证券监督管理机构规定的其他形式。 股票采用纸面形式的，应当载明下列主要事项： （一）公司名称； （二）公司成立日期或者股票发行的时间； （三）股票种类、票面金额及代表的股份数，发行无面额股的，股票代表的股份数。 股票采用纸面形式的，还应当载明股票的编号，由法定代表人签名，公司盖章。 发起人股票采用纸面形式的，应当标明发起人股票字样。</p><h3 id="第一百五十条" tabindex="-1">第一百五十条 <a class="header-anchor" href="#第一百五十条" aria-label="Permalink to &quot;第一百五十条&quot;">​</a></h3><p>十条股份有限公司成立后，即向股东正式交付股票。公司成立前不得向股东交付股票。</p><h3 id="第一百五十一条" tabindex="-1">第一百五十一条 <a class="header-anchor" href="#第一百五十一条" aria-label="Permalink to &quot;第一百五十一条&quot;">​</a></h3><p>一条公司发行新股，股东会应当对下列事项作出决议： （一）新股种类及数额； （二）新股发行价格； （三）新股发行的起止日期； （四）向原有股东发行新股的种类及数额； （五）发行无面额股的，新股发行所得股款计入注册资本的金额。 公司发行新股，可以根据公司经营情况和财务状况，确定其作价方案。</p><h3 id="第一百五十二条" tabindex="-1">第一百五十二条 <a class="header-anchor" href="#第一百五十二条" aria-label="Permalink to &quot;第一百五十二条&quot;">​</a></h3><p>二条公司章程或者股东会可以授权董事会在三年内决定发行不超过已发行股份百分之五十的股份。但以非货币财产作价出资的应当经股东会决议。 董事会依照前款规定决定发行股份导致公司注册资本、已发行股份数发生变化的，对公司章程该项记载事项的修改不需再由股东会表决。</p><h3 id="第一百五十三条" tabindex="-1">第一百五十三条 <a class="header-anchor" href="#第一百五十三条" aria-label="Permalink to &quot;第一百五十三条&quot;">​</a></h3><p>三条公司章程或者股东会授权董事会决定发行新股的，董事会决议应当经全体董事三分之二以上通过。</p><h3 id="第一百五十四条" tabindex="-1">第一百五十四条 <a class="header-anchor" href="#第一百五十四条" aria-label="Permalink to &quot;第一百五十四条&quot;">​</a></h3><p>四条公司向社会公开募集股份，应当经国务院证券监督管理机构注册，公告招股说明书。 招股说明书应当附有公司章程，并载明下列事项： （一）发行的股份总数； （二）面额股的票面金额和发行价格或者无面额股的发行价格； （三）募集资金的用途； （四）认股人的权利和义务； （五）股份种类及其权利和义务； （六）本次募股的起止日期及逾期未募足时认股人可以撤回所认股份的说明。 公司设立时发行股份的，还应当载明发起人认购的股份数。</p><h3 id="第一百五十五条" tabindex="-1">第一百五十五条 <a class="header-anchor" href="#第一百五十五条" aria-label="Permalink to &quot;第一百五十五条&quot;">​</a></h3><p>五条公司向社会公开募集股份，应当由依法设立的证券公司承销，签订承销协议。</p><h3 id="第一百五十六条" tabindex="-1">第一百五十六条 <a class="header-anchor" href="#第一百五十六条" aria-label="Permalink to &quot;第一百五十六条&quot;">​</a></h3><p>六条公司向社会公开募集股份，应当同银行签订代收股款协议。 代收股款的银行应当按照协议代收和保存股款，向缴纳股款的认股人出具收款单据，并负有向有关部门出具收款证明的义务。 公司发行股份募足股款后，应予公告。 第二节股份转让</p><h3 id="第一百五十七条" tabindex="-1">第一百五十七条 <a class="header-anchor" href="#第一百五十七条" aria-label="Permalink to &quot;第一百五十七条&quot;">​</a></h3><p>七条股份有限公司的股东持有的股份可以向其他股东转让，也可以向股东以外的人转让；公司章程对股份转让有限制的，其转让按照公司章程的规定进行。</p><h3 id="第一百五十八条" tabindex="-1">第一百五十八条 <a class="header-anchor" href="#第一百五十八条" aria-label="Permalink to &quot;第一百五十八条&quot;">​</a></h3><p>八条股东转让其股份，应当在依法设立的证券交易场所进行或者按照国务院规定的其他方式进行。</p><h3 id="第一百五十九条" tabindex="-1">第一百五十九条 <a class="header-anchor" href="#第一百五十九条" aria-label="Permalink to &quot;第一百五十九条&quot;">​</a></h3><p>九条股票的转让，由股东以背书方式或者法律、行政法规规定的其他方式进行；转让后由公司将受让人的姓名或者名称及住所记载于股东名册。 股东会会议召开前二十日内或者公司决定分配股利的基准日前五日内，不得变更股东名册。法律、行政法规或者国务院证券监督管理机构对上市公司股东名册变更另有规定的，从其规定。</p><h3 id="第一百六十条" tabindex="-1">第一百六十条 <a class="header-anchor" href="#第一百六十条" aria-label="Permalink to &quot;第一百六十条&quot;">​</a></h3><p>十条公司公开发行股份前已发行的股份，自公司股票在证券交易所上市交易之日起一年内不得转让。法律、行政法规或者国务院证券监督管理机构对上市公司的股东、实际控制人转让其所持有的本公司股份另有规定的，从其规定。 公司董事、监事、高级管理人员应当向公司申报所持有的本公司的股份及其变动情况，在就任时确定的任职期间每年转让的股份不得超过其所持有本公司股份总数的百分之二十五；所持本公司股份自公司股票上市交易之日起一年内不得转让。上述人员离职后半年内，不得转让其所持有的本公司股份。公司章程可以对公司董事、监事、高级管理人员转让其所持有的本公司股份作出其他限制性规定。 股份在法律、行政法规规定的限制转让期限内出质的，质权人不得在限制转让期限内行使质权。</p><h3 id="第一百六十一条" tabindex="-1">第一百六十一条 <a class="header-anchor" href="#第一百六十一条" aria-label="Permalink to &quot;第一百六十一条&quot;">​</a></h3><p>一条有下列情形之一的，对股东会该项决议投反对票的股东可以请求公司按照合理的价格收购其股份，公开发行股份的公司除外： （一）公司连续五年不向股东分配利润，而公司该五年连续盈利，并且符合本法规定的分配利润条件； （二）公司转让主要财产； （三）公司章程规定的营业期限届满或者章程规定的其他解散事由出现，股东会通过决议修改章程使公司存续。 自股东会决议作出之日起六十日内，股东与公司不能达成股份收购协议的，股东可以自股东会决议作出之日起九十日内向人民法院提起诉讼。 公司因本条第一款规定的情形收购的本公司股份，应当在六个月内依法转让或者注销。</p><h3 id="第一百六十二条" tabindex="-1">第一百六十二条 <a class="header-anchor" href="#第一百六十二条" aria-label="Permalink to &quot;第一百六十二条&quot;">​</a></h3><p>二条公司不得收购本公司股份。但是，有下列情形之一的除外： （一）减少公司注册资本； （二）与持有本公司股份的其他公司合并； （三）将股份用于员工持股计划或者股权激励； （四）股东因对股东会作出的公司合并、分立决议持异议，要求公司收购其股份； （五）将股份用于转换公司发行的可转换为股票的公司债券； （六）上市公司为维护公司价值及股东权益所必需。 公司因前款第一项、第二项规定的情形收购本公司股份的，应当经股东会决议；公司因前款第三项、第五项、第六项规定的情形收购本公司股份的，可以按照公司章程或者股东会的授权，经三分之二以上董事出席的董事会会议决议。 公司依照本条第一款规定收购本公司股份后，属于第一项情形的，应当自收购之日起十日内注销；属于第二项、第四项情形的，应当在六个月内转让或者注销；属于第三项、第五项、第六项情形的，公司合计持有的本公司股份数不得超过本公司已发行股份总数的百分之十，并应当在三年内转让或者注销。 上市公司收购本公司股份的，应当依照《中华人民共和国证券法》的规定履行信息披露义务。上市公司因本条第一款第三项、第五项、第六项规定的情形收购本公司股份的，应当通过公开的集中交易方式进行。 公司不得接受本公司的股份作为质权的标的。</p><h3 id="第一百六十三条" tabindex="-1">第一百六十三条 <a class="header-anchor" href="#第一百六十三条" aria-label="Permalink to &quot;第一百六十三条&quot;">​</a></h3><p>三条公司不得为他人取得本公司或者其母公司的股份提供赠与、借款、担保以及其他财务资助，公司实施员工持股计划的除外。 为公司利益，经股东会决议，或者董事会按照公司章程或者股东会的授权作出决议，公司可以为他人取得本公司或者其母公司的股份提供财务资助，但财务资助的累计总额不得超过已发行股本总额的百分之十。董事会作出决议应当经全体董事的三分之二以上通过。 违反前两款规定，给公司造成损失的，负有责任的董事、监事、高级管理人员应当承担赔偿责任。</p><h3 id="第一百六十四条" tabindex="-1">第一百六十四条 <a class="header-anchor" href="#第一百六十四条" aria-label="Permalink to &quot;第一百六十四条&quot;">​</a></h3><p>四条股票被盗、遗失或者灭失，股东可以依照《中华人民共和国民事诉讼法》规定的公示催告程序，请求人民法院宣告该股票失效。人民法院宣告该股票失效后，股东可以向公司申请补发股票。</p><h3 id="第一百六十五条" tabindex="-1">第一百六十五条 <a class="header-anchor" href="#第一百六十五条" aria-label="Permalink to &quot;第一百六十五条&quot;">​</a></h3><p>五条上市公司的股票，依照有关法律、行政法规及证券交易所交易规则上市交易。</p><h3 id="第一百六十六条" tabindex="-1">第一百六十六条 <a class="header-anchor" href="#第一百六十六条" aria-label="Permalink to &quot;第一百六十六条&quot;">​</a></h3><p>六条上市公司应当依照法律、行政法规的规定披露相关信息。</p><h3 id="第一百六十七条" tabindex="-1">第一百六十七条 <a class="header-anchor" href="#第一百六十七条" aria-label="Permalink to &quot;第一百六十七条&quot;">​</a></h3><p>七条自然人股东死亡后，其合法继承人可以继承股东资格；但是，股份转让受限的股份有限公司的章程另有规定的除外。</p><hr><p class="law-foot">本篇依据《中华人民共和国公司法》2023 年 12 月 29 日第十四届全国人大常委会第七次会议第二次修订文本，自 2024 年 7 月 1 日起施行；本站同步于 2026-11-07。</p>',55)])])}const b=e(o,[["render",i]]);export{p as __pageData,b as default};
